<?php include 'config.php'; admin_only();
function count_q($conn,$query){$r=mysqli_query($conn,$query);return $r?(int)mysqli_fetch_row($r)[0]:0;}
$total=count_q($conn,'SELECT COUNT(*) FROM books'); $available=count_q($conn,"SELECT COUNT(*) FROM books WHERE status='Available'"); $issued=count_q($conn,"SELECT COUNT(*) FROM issue_book WHERE return_date IS NULL"); $students=count_q($conn,'SELECT COUNT(*) FROM students'); $recent=mysqli_query($conn,'SELECT * FROM issue_book ORDER BY issue_date DESC LIMIT 6'); ?>
