date']); ?></td><td><span class="badge <?php echo $status; ?>"><?php echo ucfirst($status); ?></span></td></tr><?php endwhile; else: ?><tr><td colspan="4" class="empty">No circulation activity yet.</td></tr><?php endif; ?></tbody></table></div></section></main></div></body></html>
